TASK_STATUS_LABELS = {'active': 'Активна', 'done': 'Выполнена',
                      'paused': 'Приостановлена', 'archived': 'Архив'}
HYP_STATUS_LABELS = {'planned': '⏳ План', 'in_progress': '🔄 В работе',
                     'done': '✅ Готово', 'failed': '❌ Не подтв.'}
JOB_STATUS_LABELS = {'planned': '⏳', 'in_progress': '🔄', 'done': '✅', 'failed': '❌'}


def _valid_date(s):
    try:
        datetime.strptime(s, '%Y-%m-%d')
        return True
    except Exception:
        return False


def _task_active_on(t, dk):
    st = (t.get('status') or '').strip()
    if st not in ('active', 'paused'):
        return False
    sd = (t.get('start_date') or '').strip()
    dl = (t.get('deadline') or '').strip()
    if sd and dk < sd:
        return False
    if dl and dk > dl:
        return False
    return True


def _task_repr(t):
    hyp_list = []
    raw_hyps = t.get('hypotheses') or []
    if not isinstance(raw_hyps, list):
        raw_hyps = []
    for h in raw_hyps:
        if not isinstance(h, dict) or h.get('kind') != 'hypothesis':
            continue
        hid = h.get('id', '')
        jobs = []
        for tk in raw_hyps:
            if not isinstance(tk, dict) or tk.get('kind') != 'task':
                continue
            if tk.get('parent') != hid:
                continue
            jobs.append({
                'id': tk.get('id', ''),
                'title': (tk.get('title') or '')[:200],
                'status': tk.get('status', 'planned'),
                'status_label': JOB_STATUS_LABELS.get(tk.get('status', 'planned'), '⏳'),
            })
        hyp_list.append({
            'id': hid,
            'title': (h.get('title') or '')[:200],
            'status': h.get('status', 'planned'),
            'status_label': HYP_STATUS_LABELS.get(h.get('status', 'planned'), ''),
            'jobs': jobs,
        })
    return {
        'task_id': t.get('id', ''),
        'name': t.get('name', ''),
        'icon': t.get('icon', '📋'),
        'status': t.get('status', 'active'),
        'status_label': TASK_STATUS_LABELS.get(t.get('status', 'active'), ''),
        'start_date': t.get('start_date', ''),
        'deadline': t.get('deadline', ''),
        'description': (t.get('description') or '')[:2000],
        'tags': list(t.get('tags') or []),
        'is_urgent': bool(t.get('is_urgent')),
        'hypotheses': hyp_list,
    }


def _collect(db, dk):
    data = db.load_all()
    employees = data.get('employees') or []
    tasks = data.get('tasks') or []
    active_tasks = [t for t in tasks if _task_active_on(t, dk)]
    rows = []
    for e in employees:
        if e.get('fired'):
            continue
        eid = e.get('id', '')
        my = []
        for t in active_tasks:
            if eid not in (t.get('assignees') or []):
                continue
            my.append(_task_repr(t))
        if not my:
            continue
        my.sort(key=lambda x: (
            {'active': 0, 'paused': 1}.get(x.get('status', 'active'), 2),
            x.get('deadline', '9999-99-99'),
            (x.get('name') or '').lower(),
        ))
        rows.append({
            'employee_id': eid,
            'employee_name': e.get('name', eid),
            'employee_color': e.get('color', '#888'),
            'department': e.get('department', ''),
            'tasks_count': len(my),
            'tasks': my,
        })
    rows.sort(key=lambda x: (-x['tasks_count'], (x.get('employee_name') or '').lower()))
    return {
        'date': dk,
        'employees': rows,
        'totals': {
            'employees_with_tasks': len(rows),
            'tasks_assignments': sum(r['tasks_count'] for r in rows),
        },
    }


def _build_xlsx(payload):
    wb = Workbook()
    ws = wb.active
    ws.title = 'Назначено на день'
    ws.cell(1, 1, 'Назначено на день: ' + payload['date']).font = Font(bold=True, size=14)
    ws.merge_cells('A1:G1')
    hr = 3
    hdr_fill = PatternFill('solid', fgColor='FF2C3E50')
    hdr_font = Font(bold=True, color='FFFFFFFF')
    headers = ['Сотрудник', 'Отдел', 'Задача', 'Статус', 'Дедлайн', 'Описание', 'Гипотезы / Задания']
    widths = [26, 18, 40, 14, 12, 50, 50]
    for ci, (lbl, w) in enumerate(zip(headers, widths), 1):
        c = ws.cell(hr, ci, lbl)
        c.font = hdr_font
        c.fill = hdr_fill
        c.alignment = Alignment(horizontal='center', vertical='center', wrap_text=True)
        ws.column_dimensions[get_column_letter(ci)].width = w
    r = hr + 1
    for emp in payload['employees']:
        first = True
        for t in emp['tasks']:
            ws.cell(r, 1, emp['employee_name'] if first else '')
            ws.cell(r, 2, emp['department'] if first else '')
            ws.cell(r, 3, ((t['icon'] + ' ') if t['icon'] else '') + t['name'])
            ws.cell(r, 4, t['status_label'])
            ws.cell(r, 5, t['deadline'])
            ws.cell(r, 6, t['description'])
            hyp_lines = []
            for h in t.get('hypotheses', []):
                hyp_lines.append('🧪 ' + h['title'] + '  [' + h['status_label'] + ']')
                for j in h.get('jobs', []):
                    hyp_lines.append('    📌 ' + j['title'] + '  [' + j['status_label'] + ']')
            ws.cell(r, 7, chr(10).join(hyp_lines))
            for ci in (3, 4, 5, 6, 7):
                ws.cell(r, ci).alignment = Alignment(horizontal='left', vertical='top', wrap_text=True)
            first = False
            r += 1
        r += 1
    out = BytesIO()
    wb.save(out)
    out.seek(0)
    return out


