/* v1.0.12 - блок «Назначено, но не заведено»: единственный рендер, без дублей */
(function(){
'use strict';
if (window.__trkLogAssignedDedupV1012) return;
window.__trkLogAssignedDedupV1012 = true;

var _debounceTimer = null;

function _clearAllBlocks() {
    var ids = ['logAssignedWrap', 'logDayExisting'];
    for (var i = 0; i < ids.length; i++) {
        var w = document.getElementById(ids[i]);
        if (!w) continue;
        var blocks = w.querySelectorAll('.log-assigned-block');
        for (var j = 0; j < blocks.length; j++) {
            if (blocks[j].parentNode) blocks[j].parentNode.removeChild(blocks[j]);
        }
    }
}

function _refreshAssignedOnce() {
    var lm = document.getElementById('logModal');
    if (!lm || !lm.classList.contains('active')) return;

    // 1. Полная зачистка обоих контейнеров — гарантия единственного блока
    _clearAllBlocks();

    // 2. Штатный декоратор создаёт ОДИН новый блок в #logDayExisting
    try {
        if (typeof window.__trkLogAssignedDecorate === 'function') {
            window.__trkLogAssignedDecorate();
        }
    } catch (e) { console.error('[v1.0.12] decorate:', e); }

    // 3. Перенос единственного блока в видимый контейнер
    var target = document.getElementById('logAssignedWrap');
    var existing = document.getElementById('logDayExisting');
    if (target && existing) {
        var blocks = existing.querySelectorAll('.log-assigned-block');
        for (var k = 0; k < blocks.length; k++) {
            target.appendChild(blocks[k]);
        }
    }

    // 4. Видимость контейнера
    if (target) {
        var has = target.querySelector('.log-assigned-block');
        target.style.display = has ? '' : 'none';
    }
}

function _scheduleRefresh() {
    if (_debounceTimer) clearTimeout(_debounceTimer);
    _debounceTimer = setTimeout(function(){
        _debounceTimer = null;
        _refreshAssignedOnce();
    }, 100);
}

// change на сотрудника/дату — один общий триггер с debounce
document.addEventListener('change', function(e) {
    if (!e.target) return;
    if (e.target.id !== 'log_employee' && e.target.id !== 'log_date') return;
    var lm = document.getElementById('logModal');
    if (!lm || !lm.classList.contains('active')) return;
    _scheduleRefresh();
}, true);

// при открытии модалки — один рендер после отработки штатных декораторов
(function watch(){
    var lm = document.getElementById('logModal');
    if (!lm) { setTimeout(watch, 500); return; }
    if (lm._assignedDedupWatched) return;
    lm._assignedDedupWatched = true;
    new MutationObserver(function(){
        if (lm.classList.contains('active')) {
            setTimeout(_scheduleRefresh, 200);
            setTimeout(_scheduleRefresh, 500);
            setTimeout(_scheduleRefresh, 1000);
        }
    }).observe(lm, {attributes: true, attributeFilter: ['class']});
})();

window.__trkLogAssignedRefresh = _refreshAssignedOnce;
window.__trkLogAssignedDedup = _clearAllBlocks;
})();

/* v1.0.12: страховка от дублей (виден только первый .log-assigned-block в каждом контейнере) */
#logModal #logAssignedWrap .log-assigned-block ~ .log-assigned-block,
#logModal #logDayExisting .log-assigned-block ~ .log-assigned-block {
    display: none !important;
}
